AREAS = [  # (name prefix, area shown on Discord)
    ("CC_", "Card Castle"), ("FIELD", "Field of Hopes and Dreams"),
    ("FOREST", "Scarlet Forest"), ("DW_CITY", "Cyber City"),
    ("DW_CYBER", "Cyber Field"), ("DW_MANSION", "Queen's Mansion"),
    ("DW_CASTLE", "Castle Town"), ("CASTLE", "Castle Town"),
    ("DW_CHURCH", "Dark Sanctuary"), ("DW_TEEVIE", "TV World"),
    ("DW_TV", "TV World"), ("BOARD", "TV World: Board Game"),
    ("DW_B3BS", "TV World: Backstage"), ("DW_COUCH", "TV World"),
    ("DW_RANKING", "TV World"), ("DW_SNOW", "TV World"),
    ("DW_GARDEN", "Garden"), ("DW_CLIFF", "Cliffs"), ("DW_FCASTLE", "Castle"),
    ("DARK", "Dark World"), ("LW_", "Hometown"), ("TOWN", "Hometown"),
    ("TOR", "Hometown"), ("KRIS", "Hometown"), ("SCHOOL", "Hometown"),
    ("HOSPITAL", "Hometown"), ("DINER", "Hometown"), ("LIBRARY", "Hometown"),
    ("FLOWERSHOP", "Hometown"), ("TOWNHALL", "Hometown"),
    ("GRAVEYARD", "Hometown"), ("BEACH", "Hometown"), ("ALPHYS", "Hometown"),
]

def place_of(room):
    raw = ROOMS.get(room)
    if not raw:
        return None, None
    area = next((a for p, a in AREAS if raw.startswith(p)), None)
    spot = raw
    for p in ("DW_", "LW_", "CC_"):
        if spot.startswith(p):
            spot = spot[len(p):]
    words = spot.split("_")
    if len(words) > 1 and words[0] in ("CHURCH", "CHURCHB", "CHURCHC", "CYBER", "CITY",
            "MANSION", "TEEVIE", "TV", "FOREST", "FIELD", "TOWN", "CASTLE", "GARDEN", "CLIFF", "FCASTLE"):
        words = words[1:]
    spot = " ".join(words).title()
    return area, spot

# Save-point rooms right before the bosses (room number from the save file)
BOSSES = {
    10392: "Jevil", 10407: "King",
    20181: "Spamton NEO", 20004: "Spamton NEO (Weird Route)",
    30108: "The Roaring Knight", 30134: "Tenna",
    40281: "The Titan", 40115: "Gerson (Hammer of Justice)", 40300: "MIKE",
}

def mtime(p):
    try:
        return os.path.getmtime(p)
    except Exception:
        return 0

def newest_save():
    files = [f for f in glob.glob(os.path.join(FOLDER, "filech*_*"))
             if re.search(r"filech\d+_\d$", f)]
    return max(files, key=mtime) if files else None

def read_lines(path):
    try:
        with open(path, encoding="utf-8", errors="ignore") as f:
            return [l.strip() for l in f.read().splitlines()]
    except Exception:
        return []

def build_status():
    path = newest_save()
    if not path:
        return {"details": "Playing DELTARUNE", "large_image": ICON}
    ch = int(re.search(r"filech(\d+)_", path).group(1))
    lines = [l for l in read_lines(path)]
    while lines and lines[-1] == "":
        lines.pop()
    name = lines[0] if lines else "?"
    try:
        room = int(float(lines[-2]))   # 2nd-to-last line is the room, last is play time
    except Exception:
        room = -1
    boss = BOSSES.get(room)
    title = CHAPTERS.get(ch, f"Chapter {ch}")
    area, spot = place_of(room)
    if boss:
        details = f"Fighting {boss}"
    elif area:
        details = f"{area}: {spot}"
    elif spot:
        details = spot
    else:
        details = f"Chapter {ch}: {title}"
    state = f"{name} | Chapter {ch}: {title}"
    return {"details": details[:128], "state": state[:128],
            "large_image": ICON, "large_text": f"Chapter {ch}: {title} | Room {room}"}

def deltarune_running():
    out = subprocess.run(["tasklist", "/FO", "CSV", "/NH"],
                         capture_output=True, text=True).stdout.lower()
    return "deltarune" in out

def main():
    if not CLIENT_ID.isdigit():
        print("Discord application ID is missing from deltarune_status.py.")
        input("Press Enter to close...")
        return
    rpc = Presence(CLIENT_ID)
    rpc.connect()
    print("Connected to Discord. Leave this window open while you play.")
    me = os.path.abspath(__file__)
    my_mtime = mtime(me)
    start, last = None, None
    while True:
        if mtime(me) != my_mtime:
            print("Script updated - restarting...")
            try:
                rpc.close()
            except Exception:
                pass
            os.execv(sys.executable, [sys.executable, me])
        if deltarune_running():
            if start is None:
                start = int(time.time())
            status = build_status()
            if status != last:
                rpc.update(start=start, **status)
                print(time.strftime("%H:%M:%S"), "-", status.get("details"), "/", status.get("state", ""))
                last = status
        elif last is not None:
            rpc.clear()
            start, last = None, None
        time.sleep(3)

if __name__ == "__main__":
    main()
